package dev.baranhan.viltrumitecore.hero.control;

import static org.junit.jupiter.api.Assertions.*;
import java.io.*;
import java.nio.file.*;
import java.util.*;
import net.minecraft.nbt.*;
import net.minecraft.world.phys.Vec3;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.ValueSource;

/** Real NbtIo binary round-trip and actual captured control records, not a copied helper. */
class WorldPauseFlagsTest {
   final UUID effect=UUID.randomUUID(),owner=UUID.randomUUID(),target=UUID.randomUUID();
   static CompoundTag disk(CompoundTag tag)throws Exception{var out=new ByteArrayOutputStream();NbtIo.write(tag,new DataOutputStream(out));return NbtIo.read(new DataInputStream(new ByteArrayInputStream(out.toByteArray())));}
   @ParameterizedTest @ValueSource(booleans={false,true}) void newProcessRestoresTheNaturalGravityFromSavedEntityNbt(boolean natural)throws Exception{var data=new CompoundTag();PauseFlagRecovery.remember(data,effect,new PauseFlagRecovery.Flags(natural,false));var entity=new CompoundTag();entity.putBoolean("NoGravity",true);entity.put("ForgeData",data);var loaded=disk(entity);var flags=PauseFlagRecovery.recover(loaded.getCompound("ForgeData"),null,false);assertNotNull(flags);loaded.putBoolean("NoGravity",flags.noGravity());assertEquals(natural,loaded.getBoolean("NoGravity"));assertNull(PauseFlagRecovery.recover(loaded.getCompound("ForgeData"),null,false));}
   @ParameterizedTest @ValueSource(booleans={false,true}) void savedMobNoAiRestoresAfterLostRuntimeMaps(boolean natural)throws Exception{var data=new CompoundTag();PauseFlagRecovery.remember(data,effect,new PauseFlagRecovery.Flags(false,natural));var saved=disk(data);var restored=PauseFlagRecovery.recover(saved,null,false);assertFalse(restored.noGravity());assertEquals(natural,restored.noAi());}
   @Test void repeatedRefreshNeverRecapturesFrozenFlags(){var data=new CompoundTag();PauseFlagRecovery.remember(data,effect,new PauseFlagRecovery.Flags(false,false));for(int i=0;i<10;i++)PauseFlagRecovery.remember(data,effect,new PauseFlagRecovery.Flags(true,true));var saved=PauseFlagRecovery.recover(data,null,false);assertFalse(saved.noGravity());assertFalse(saved.noAi());}
   @Test void liveOwnLeaseIsKept(){var data=new CompoundTag();PauseFlagRecovery.remember(data,effect,new PauseFlagRecovery.Flags(false,false));assertNull(PauseFlagRecovery.recover(data,effect,false));assertTrue(data.contains(PauseFlagRecovery.TAG));assertNotNull(PauseFlagRecovery.recover(data,null,false));}
   @Test void foreignRecordCannotHaveItsFlagsOverwritten(){var data=new CompoundTag();PauseFlagRecovery.remember(data,effect,new PauseFlagRecovery.Flags(false,false));assertNull(PauseFlagRecovery.recover(data,UUID.randomUUID(),false));assertFalse(data.contains(PauseFlagRecovery.TAG));}
   @Test void intentionalLimboGravityWinsOverAnOldBodyLease(){var data=new CompoundTag();PauseFlagRecovery.remember(data,effect,new PauseFlagRecovery.Flags(false,false));assertNull(PauseFlagRecovery.recover(data,null,true));assertFalse(data.contains(PauseFlagRecovery.TAG));}
   @Test void onlyMatchingOwnerCanForgetTheLease(){var data=new CompoundTag();PauseFlagRecovery.remember(data,effect,new PauseFlagRecovery.Flags(false,false));PauseFlagRecovery.forget(data,UUID.randomUUID());assertTrue(data.contains(PauseFlagRecovery.TAG));PauseFlagRecovery.forget(data,effect);assertFalse(data.contains(PauseFlagRecovery.TAG));}
   @Test void malformedSavedLeaseNeverInventsOriginalFlags(){var data=new CompoundTag();var lease=new CompoundTag();lease.putUUID("effect",effect);lease.putString("noGravity","bad");data.put(PauseFlagRecovery.TAG,lease);assertNull(PauseFlagRecovery.recover(data,null,false));assertFalse(data.contains(PauseFlagRecovery.TAG));}
   @Test void malformedMarkerTypeIsRemovedWithoutRestoring(){var data=new CompoundTag();data.putString(PauseFlagRecovery.TAG,"bad");assertNull(PauseFlagRecovery.recover(data,null,false));assertFalse(data.contains(PauseFlagRecovery.TAG));}
   ControlManager manager(ControlManager.ControlRecord record)throws Exception{var ctor=ControlManager.class.getDeclaredConstructor();ctor.setAccessible(true);var cm=ctor.newInstance();var f=ControlManager.class.getDeclaredField("controls");f.setAccessible(true);@SuppressWarnings("unchecked") var records=(Map<UUID,ControlManager.ControlRecord>)f.get(cm);records.put(target,record);return cm;}
   @Test void actualManagerStoresRecordOriginalsNotTheFrozenCurrentBody()throws Exception{var record=new ControlManager.ControlRecord(target,owner,effect,ControlKind.FREEZE,new Vec3(1,80,3),false,true);var cm=manager(record);var data=new CompoundTag();assertTrue(cm.rememberPauseFlags(target,owner,effect,data));for(int i=0;i<10;i++){assertTrue(cm.refresh(target,owner,effect,ControlKind.FREEZE,100+i));assertTrue(cm.rememberPauseFlags(target,owner,effect,data));}var restored=PauseFlagRecovery.recover(disk(data),null,false);assertFalse(restored.noGravity());assertTrue(restored.noAi());assertEquals(109,record.expiresAt);}
   @Test void foreignCasterEffectAndKindCannotInstallALease()throws Exception{var record=new ControlManager.ControlRecord(target,owner,effect,ControlKind.FREEZE,Vec3.ZERO,false,false);var cm=manager(record);var data=new CompoundTag();assertFalse(cm.rememberPauseFlags(target,UUID.randomUUID(),effect,data));assertFalse(cm.rememberPauseFlags(target,owner,UUID.randomUUID(),data));record.kind=ControlKind.PULL;assertFalse(cm.rememberPauseFlags(target,owner,effect,data));assertFalse(data.contains(PauseFlagRecovery.TAG));}
   @ParameterizedTest @ValueSource(booleans={false,true}) void participantLogoutReleasesBeforeVanillaSaveAndNewProcess(boolean natural)throws Exception{var f=new LogoutFixture(natural);var session=new WorldPause.Session(owner,effect,150,true,32);session.sync(f);assertTrue(f.noGravity);session.leave(f,target);var entity=disk(f.save());assertEquals(natural,entity.getBoolean("NoGravity"));assertFalse(entity.getCompound("ForgeData").contains(PauseFlagRecovery.TAG));assertFalse(session.isPaused(target));}
   @Test void liveLogoutHookAndRecoveryAreWiredAtTheActualSeams()throws Exception{var source=Files.readString(Path.of("src/main/java/dev/baranhan/viltrumitecore/hero/HeroEvents.java"));var logout=source.substring(source.indexOf("public static void onPlayerLogout("),source.indexOf("public static void onPlayerLogin("));assertTrue(logout.contains("WorldPause.onLeave(player)"));assertTrue(logout.indexOf("WorldPause.onLeave(player)")<logout.indexOf("HeroRegistry.get(player).cleanup"));var manager=Files.readString(Path.of("src/main/java/dev/baranhan/viltrumitecore/hero/control/ControlManager.java"));assertTrue(manager.contains("PauseFlagRecovery.recover("));assertTrue(manager.contains("PauseFlagRecovery.forget("));}
   final class LogoutFixture implements WorldPause.Backend {
      final WorldPause.Target key=new WorldPause.Target(target,"minecraft:overworld");final CompoundTag data=new CompoundTag();final boolean natural;boolean noGravity;ControlManager.ControlRecord record;
      LogoutFixture(boolean natural){this.natural=natural;noGravity=natural;}
      public List<WorldPause.Target> players(){return List.of(key);}public List<WorldPause.Target> hostiles(List<WorldPause.Target> players,int radius){return List.of();}public long now(WorldPause.Target t){return 0;}
      public void freeze(WorldPause.Target t,UUID caster,UUID id,long until){if(record==null)record=new ControlManager.ControlRecord(target,caster,id,ControlKind.FREEZE,Vec3.ZERO,noGravity,false);ControlManager.refreshRecord(record,caster,id,ControlKind.FREEZE,until);PauseFlagRecovery.remember(data,id,new PauseFlagRecovery.Flags(record.savedNoGravity,record.savedNoAi));noGravity=true;}
      public void release(WorldPause.Target t,UUID id,ReleaseReason reason){if(record!=null&&record.effectId.equals(id)){noGravity=record.savedNoGravity;PauseFlagRecovery.forget(data,id);record=null;}}
      CompoundTag save(){var saved=new CompoundTag();saved.putBoolean("NoGravity",noGravity);saved.put("ForgeData",data.copy());return saved;}
   }
}
